Translate("deDE", "hillsbrad-foothills", {
	title = "Vorgebirge von Hillsbrad",
	aliases = { "Hillsbrad" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Vorgebirge von Hillsbrad ist die grüne Südmark des alten Königreichs {link:lordaeron}Lordaeron{/link}. Es reicht vom Schnee des {link:alterac-mountains}Alteracgebirges{/link} hinab zu einer milden Küste am Meer. Die Seuche, die Lordaeron tötete, ging an ihm vorüber, und eine kleine Weile schien Hillsbrad verschont. Das war es nicht. Heute ist das Vorgebirge ein Schlachtfeld. Die {link:humans}Menschen{/link} von {link:southshore}Southshore{/link} halten die Küste, die {link:forsaken}Verlassenen{/link} halten {link:tarren-mill}Tarrens Mühle{/link} im Norden, und zwischen ihnen brennen die Höfe von Hillsbrad einer nach dem anderen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann sich die ersten Dörfer in diesen Hügeln erhoben. Sie gehörten zu {link:lordaeron}Lordaeron{/link}, solange dieses Königreich bestand. An der Ostgrenze steht der uralte Wall, der den Namen Thoradins trägt, des Gründers von {link:arathor}Arathor{/link}. Als {link:stormwind-city}Stormwind{/link} im {link:first-war}Ersten Krieg{/link} fiel, gingen seine Flüchtlinge in {link:southshore}Southshore{/link} an Land, und Hillsbrad war das erste Land des Nordens, das sie empfing.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Hillsbrad ist zwischen zwei Kriegen gefangen. {link:high-executor-darthalia}Hochexekutor Darthalia{/link} befehligt die Verlassenen von {link:tarren-mill}Tarrens Mühle{/link} im Namen der {link:sylvanas-windrunner}Dunklen Fürstin{/link} und von {link:varimathras}Varimathras{/link}. Ihre Todeswachen überfallen die Höfe der Felder von Hillsbrad, und die Apotheker der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} erproben ihre neuen Gifte an den Bauern und ihren Tieren. {link:southshore}Southshore{/link} und die {link:dwarves}Zwerge{/link} von {link:dun-garok}Dun Garok{/link} antworten mit den wenigen Soldaten, die sie haben. Unterdessen macht das {link:syndicate}Syndikat{/link} von den Ruinen der {link:durnholde-keep}Burg Durnholde{/link} aus Jagd auf beide Seiten. Man glaubt, dass seine Meuchelmörder bereits einen Magistrat von Southshore ermordet haben, und sie jagen den nächsten. {link:orcs}Orcs{/link}, die {link:thrall}Thrall{/link} selbst geschickt hat, sind vor Kurzem nach Tarrens Mühle gekommen, denn Durnholde war einst das Gefängnis des Kriegshäuptlings, und er will etwas von dort zurück.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Leute von {link:southshore}Southshore{/link}.{/b} Fischer, Soldaten und Gelehrte, treu der {link:alliance}Allianz{/link}.
• {b}Die Bauern von Hillsbrad.{/b} Sie bestellen noch die Felder westlich des Flusses, unter den Augen des Feindes.
• {b}Die Verlassenen.{/b} Ihre Todeswachen, Todespirscher und Apotheker halten {link:tarren-mill}Tarrens Mühle{/link}.
• {b}{link:orcs}Orcs{/link} der {link:horde}Horde{/link}.{/b} Eine kleine Schar, entsandt aus {link:durotar}Durotar{/link}, und ein Schmied, der still in Tarrens Mühle arbeitet.
• {b}Die Zwerge von {link:dun-garok}Dun Garok{/link}.{/b} Eine Garnison von {link:dwarves}Zwergen{/link} im Südosten, die geschworen hat, die {link:humans}Menschen{/link} und ihre Mine zu verteidigen.
• {b}Das {link:syndicate}Syndikat{/link}.{/b} Diebe und Schattenmagier im Dienst der gefallenen Fürsten von {link:alterac-mountains}Alterac{/link}.
• {b}Tiere und Plünderer.{/b} {link:murlocs}Murlocs{/link} am {link:western-strand}Weststrand{/link}, {link:naga}Naga{/link} am {link:eastern-strand}Oststrand{/link}, {link:gnolls}Gnolle{/link} in der {link:nethander-stead}Nethander-Siedlung{/link} und {link:ogres}Oger{/link}, die aus Alterac herabkommen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Flüchtlinge.{/b} Nach dem Fall von {link:stormwind-city}Stormwind{/link} überquerten die Überlebenden das Meer und landeten in {link:southshore}Southshore{/link}. Von dort wurde die Kunde von den {link:orcs}Orcs{/link} zu König {link:terenas-menethil}Terenas Menethil{/link} getragen.
• {b}Der Zweite Krieg.{/b} {link:anduin-lothar}Anduin Lothar{/link} sammelte die Heere der {link:alliance}Allianz{/link} in Hillsbrad. Die {link:horde}Horde{/link} landete nahe Southshore, und hier trafen die beiden Heere in der ersten großen Landschlacht des {link:second-war}Zweiten Krieges{/link} aufeinander. Hier standen auch die Todesritter der Horde zum ersten Mal den Paladinen von {link:uther-the-lightbringer}Uther dem Lichtbringer{/link} gegenüber.
• {b}Die Lager.{/b} Nach dem Krieg wurde {link:durnholde-keep}Burg Durnholde{/link} zum Sitz der Lager, in denen die besiegten Orcs festgehalten wurden. In ihren Hallen wuchs ein junger Orc namens {link:thrall}Thrall{/link} als Sklave auf. Er entkam, kehrte an der Spitze einer neuen Horde zurück und legte die Burg in Trümmer.
• {b}Die Gegenwart.{/b} {link:lordaeron}Lordaeron{/link} ist dahin, und selbst seine südlichen Hügel entgleiten den Händen der {link:humans}Menschen{/link}.]=],
		},
		{
			title = "Überlieferungen des Vorgebirges",
			text = [=[• Die Leute von {link:southshore}Southshore{/link} sagen, ihre Köche seien die besten nördlich von {link:stormwind-city}Stormwind{/link}. Reisende sind von so weit her wie {link:darkshire}Dunkelhain{/link} gekommen, um eine Schale von Koch Jessens Schildkrötencremesuppe zu essen.
• Ein Zauberer namens {link:helcular}Helcular{/link} liegt auf dem Friedhof von Southshore begraben. Er wurde von einer Menge Stadtbewohner getötet, bevor sein finsteres Ritual vollendet war. Manche in {link:tarren-mill}Tarrens Mühle{/link} wollen es zu Ende bringen.]=],
		},
	},
})

Translate("deDE", "southshore", {
	title = "Southshore",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Southshore ist eine Hafenstadt an der Südküste von {link:hillsbrad-foothills}Hillsbrad{/link}, gebaut um ihren Hafen, ihr Gasthaus und ihr Rathaus. Sie war ein Fischerdorf, als die Flüchtlinge aus {link:stormwind-city}Stormwind{/link} dort an Land gingen. Sie ist noch immer der {link:alliance}Allianz{/link} treu und heute eine der letzten Menschenstädte des Nordens. {link:magistrate-henry-maleb}Magistrat Henry Maleb{/link} regiert sie, und {link:marshal-redpath}Marschall Redpath{/link} befehligt ihre Wache. Das {link:syndicate}Syndikat{/link} hat ihren Untergang geschworen, und die {link:forsaken}Verlassenen{/link} von {link:tarren-mill}Tarrens Mühle{/link} sagen offen, dass Southshore nach Hillsbrad brennen wird.]=],
		},
		{
			title = "Der Hafen",
			text = [=[Von ihrem Hügel aus fliegen Greifen. Seit Kurzem legen neue Schiffe an ihrem Pier an, die zum {link:menethil-harbor}Hafen von Menethil{/link} und nach {link:auberdine}Auberdine{/link} im fernen {link:kalimdor}Kalimdor{/link} segeln. Auch ein Gesandter der {link:kirin-tor}Kirin Tor{/link} ist in die Stadt gekommen, um zu bleiben.]=],
		},
	},
})

Translate("deDE", "tarren-mill", {
	title = "Tarrens Mühle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tarrens Mühle war eine Menschenstadt Lordaerons, gelegen zwischen Obstgärten in den Hügeln unterhalb von {link:alterac-mountains}Alterac{/link}. Ihre Kirche und ihre Häuser stehen noch, doch ihre Obstgärten sind verdorrt, und ihre Bewohner sind die Toten. Die {link:forsaken}Verlassenen{/link} halten sie als ihre Festung im Süden. Von hier aus führt {link:high-executor-darthalia}Hochexekutor Darthalia{/link} Krieg gegen {link:hillsbrad-foothills}Hillsbrad{/link}, und die Apotheker der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} brauen ihre Seuchen. Fledermäuse tragen Reiter nach {link:undercity}Undercity{/link}. Auch eine Schar {link:orcs}Orcs{/link}, die {link:thrall}Thrall{/link} geschickt hat, hat ihr Lager in der Stadt, denn die Ruinen von {link:durnholde-keep}Durnholde{/link} liegen gleich jenseits des Flusses.]=],
		},
	},
})

Translate("deDE", "durnholde-keep", {
	title = "Burg Durnholde",
	aliases = { "Durnholde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Durnholde war einst die stärkste Festung im südlichen {link:lordaeron}Lordaeron{/link}. Nach dem Zweiten Krieg war sie der Sitz der Lager, in denen die besiegten {link:orcs}Orcs{/link} festgehalten wurden, und Generalleutnant {link:aedelas-blackmoore}Aedelas Blackmoore{/link} herrschte über sie. Hier wuchs der kleine {link:thrall}Thrall{/link} als Sklave auf. Als er als Kriegshäuptling zurückkehrte, brach er ihre Mauern und begrub ihren Herrn unter den Steinen. Das {link:syndicate}Syndikat{/link} hat die Ruinen eingenommen. Seine Schattenmagier arbeiten dort, und seine Kerkermeister halten Orcgefangene in den alten Zellen. Ein Orc namens Gorgrash ist ihnen vor Kurzem entflohen, und er wartet nahe den Mauern.]=],
		},
	},
})

Translate("deDE", "hillsbrad-fields", {
	title = "Die Felder von Hillsbrad",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Felder von Hillsbrad sind das Ackerland westlich des Flusses, und in ihrer Mitte liegt die Stadt {link:hillsbrad-foothills}Hillsbrad{/link}. Ihr {link:magistrate-burnside}Magistrat Burnside{/link} und sein Rat verwahren die alte Urkunde der Stadt, die Proklamation von Hillsbrad, und ihr Bürgerverzeichnis. Ihre Schmiede hält einen Vorrat an Eisen. Ihre Höfe ernähren das ganze Vorgebirge. Deshalb schlagen die Verlassenen hier zuerst zu. Todeswachen überfallen die nördlichen Höfe, Bauern fliehen in die südlichen Obstgärten, und die Stadt wartet auf einen Angriff, den sie nicht hoffen kann abzuwehren.]=],
		},
	},
})

Translate("deDE", "azurelode-mine", {
	title = "Der Azurschacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Azurschacht liegt in den Hügeln südlich von {link:hillsbrad-foothills}Hillsbrad{/link}, oberhalb des Weststrands. Sein Eisen versorgt die Schmieden der {link:alliance}Allianz{/link}. Vorarbeiter Bonds hält seine Bergleute bei der Arbeit, und Wachposten stehen an seinem Eingang. Die Allianz schützt ihn erbittert. Die {link:forsaken}Verlassenen{/link} wollen ihn unbedingt. Die Dunkle Fürstin braucht Eisen, um ihre Soldaten zu bewaffnen, und eine den {link:humans}Menschen{/link} abgenommene Mine würde es ihr geben. Die Bergleute haben Grund zur Furcht. Der Name ihres Vorarbeiters steht auf der Liste des Hochexekutors.]=],
		},
	},
})

Translate("deDE", "dun-garok", {
	title = "Dun Garok",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dun Garok ist eine Zwergenfestung im Südosten von {link:hillsbrad-foothills}Hillsbrad{/link}, errichtet am {link:thoradin-s-wall}Thoradinswall{/link}. Ihre Garnison aus Bergsteigern, Schützen und Priestern wird von {link:captain-ironhill}Hauptmann Ironhill{/link} angeführt. Die {link:dwarves}Zwerge{/link} kamen, um den {link:humans}Menschen{/link} des Vorgebirges zu helfen, und sie halten Wache über deren Lande. Sie brauen ein kräftiges Starkbier, und sie sind sich nicht zu schade, einem unachtsamen Späher der Verlassenen die Ausrüstung abzunehmen, wenn sie ihn finden. {link:tarren-mill}Tarrens Mühle{/link} zählt sie zu ihren schlimmsten Feinden. Ihre Befehle sind klar: Dun Garok muss fallen.]=],
		},
	},
})

Translate("deDE", "nethander-stead", {
	title = "Nethander-Siedlung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nethander-Siedlung ist ein verlassener Hof östlich von {link:southshore}Southshore{/link}, jenseits des Flusses. Keine Aufzeichnung sagt, was aus der Familie Nethander wurde. Die {link:gnolls}Gnolle{/link} der Morastschnauzen leben nun auf ihren Feldern, und bleiche Pilze, die man Morastschnauzenblüten nennt, wachsen dicht zwischen dem Unkraut. Die Blüten stinken, und die Apotheker von {link:tarren-mill}Tarrens Mühle{/link} schätzen sie genau deshalb. Sie sind das Herz eines der tödlichsten Gebräue der Vereinigung. {link:apothecary-lydon}Apotheker Lydon{/link} hat gesagt, die dreckigen Gnolle seien also doch zu etwas gut.]=],
		},
	},
})

Translate("deDE", "purgation-isle", {
	title = "Fegefeuer-Insel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Fegefeuer-Insel ist eine steile Insel vor der Südwestküste von {link:hillsbrad-foothills}Hillsbrad{/link}, gekrönt von einem verfallenen Turm und umgeben von einem alten Friedhof. Ihre Toten ruhen nicht. Verdammte Kleriker, Mönche und Akolythen wandeln zwischen den Gräbern neben verfluchten Paladinen und Justikaren und sich windenden Magiern. Ihre Macht ist groß, weit größer als die der Tiere und Plünderer des Festlands. Keine Chronik verzeichnet, wer sie im Leben waren, welches Verbrechen oder welches Verhängnis sie an die Insel band oder warum so viele Diener des Lichts unter ihnen sind.]=],
		},
	},
})

Translate("deDE", "darrow-hill", {
	title = "Darrow Hill",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Darrow Hill erhebt sich im Norden von {link:hillsbrad-foothills}Hillsbrad{/link}, unterhalb der Höhen von {link:alterac-mountains}Alterac{/link}. Berglöwen und Hirsche streifen über seine Hänge, und Yetis hausen in den Höhlen darüber. Es ist wildes Land, und keine Stadt steht darauf. In diesen Hügeln hatte der Zauberer {link:helcular}Helcular{/link} seinen verborgenen Unterschlupf, bis die Stadtbewohner von {link:southshore}Southshore{/link} ihn fanden. Die Yetis haben seine Höhlen seither eingenommen, und seine Ritualfeuer brennen noch im Dunkeln. Der Unterschlupf war ein Geheimnis, und keine Aufzeichnung verrät, wie die Stadtbewohner davon erfuhren.]=],
		},
	},
})

Translate("deDE", "eastern-strand", {
	title = "Oststrand",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Oststrand ist das felsige Ufer östlich von {link:southshore}Southshore{/link}, das hinab bis nach {link:dun-garok}Dun Garok{/link} reicht. Die {link:naga}Naga{/link} der Daggerspine sind aus dem Meer heraufgekommen, um es für sich zu beanspruchen. Ihre Sirenen und Uferpirscher jagen am Strand entlang, und unter ihnen jagt eine Naga von seltener Macht namens Lady Zephris. Die Offiziere von Southshore fürchten, was die Naga wollen, und Kunde von ihnen hat das Oberkommando der {link:alliance}Allianz{/link} erreicht. Niemand in Southshore kann sagen, woher die Naga kamen.]=],
		},
	},
})

Translate("deDE", "western-strand", {
	title = "Weststrand",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Weststrand ist das lange Ufer westlich von {link:southshore}Southshore{/link}, unterhalb des Azurschachts. Die {link:murlocs}Murlocs{/link} der Torn Fin haben ihre Lager daran errichtet, nahe genug an der Stadt, um ihre Wache zu beunruhigen. {link:marshal-redpath}Marschall Redpath{/link} will sie zurückgedrängt sehen und verlangt ihre Köpfe als Beweis. Sein Leutnant trinkt lieber, als zu gehen, und die Aufgabe fällt meist Fremden zu. Der Leutnant hat seit Wochen keinen Fisch gegessen. Ein Murloc des Stammes namens Scargil wird selten gesehen und von denen, die ihm begegnen, selten vergessen.]=],
		},
	},
})

Translate("deDE", "southpoint-tower", {
	title = "Southpoint-Turm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Southpoint-Turm ist ein verfallener Wachturm am äußersten Westrand von {link:hillsbrad-foothills}Hillsbrad{/link}, an der Straße nach {link:silverpine-forest}Silberwald{/link}. Einst bewachte er den Zugang zum Vorgebirge. Nun verbirgt er einen einzelnen Späher der Verlassenen. Von seinen zerbrochenen Mauern aus beobachtet {link:deathstalker-lesh}Todespirscherin Lesh{/link} die Stadt Hillsbrad und schickt Nachricht nach Osten nach {link:tarren-mill}Tarrens Mühle{/link}. Sie ist allein, fern jeder Hilfe, mit den Straßen der {link:alliance}Allianz{/link} rings um sie. Ihre letzte Nachricht war kurz. Sie besagte, dass die Zeit zum Zuschlagen gekommen sei.]=],
		},
	},
})

Translate("deDE", "thoradin-s-wall", {
	title = "Thoradinswall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Thoradinswall ist ein großer, zerbrochener Schutzwall, der das {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link} vom {link:arathi-highlands}Arathihochland{/link} trennt. Er trägt den Namen Thoradins, des ersten Königs von {link:arathor}Arathor{/link}, und er ist älter als jedes Königreich, das heute besteht. Die meisten sagen, er sei errichtet worden, um die {link:trolls}Trolle{/link} der Amani zurückzuhalten. Seine Steine sind geborsten und seine Türme verschwunden, doch er markiert noch immer die Grenze. Die {link:dwarves}Zwerge{/link} von {link:dun-garok}Dun Garok{/link} bauten ihre Festung in seinem Schatten. Reisende auf dem Weg ins Arathihochland müssen ihn noch immer überqueren.]=],
		},
	},
})

Translate("deDE", "aedelas-blackmoore", {
	title = "Aedelas Blackmoore",
	subtitle = "Herr von Durnholde",
	allegiance = "Königreich Lordaeron · Burg Durnholde",
	aliases = { "Blackmoore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aedelas Blackmoore war der Herr der {link:durnholde-keep}Burg Durnholde{/link} und der Herr der Lager, in denen die besiegten {link:orcs}Orcs{/link} nach dem {link:second-war}Zweiten Krieg{/link} festgehalten wurden. Er war ein harter Kämpfer, ein schwerer Trinker und ein Mann von großem Ehrgeiz. Er fand in der Wildnis einen verwaisten Orcsäugling und zog ihn als Sklaven auf. Dieser Orc war {link:thrall}Thrall{/link}. Blackmoore wollte eine Waffe aus ihm machen. Stattdessen wurde Thrall der Kriegshäuptling, der die Orcs befreite und ihn tötete.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Blackmoore ist der Mann, der {link:thrall}Thrall{/link} formte, in jedem Sinne, den er nicht beabsichtigte. Seine Grausamkeit lehrte den jungen {link:orcs}Orc{/link}, was {link:humans}Menschen{/link} sein konnten. Die Güte anderer in seinem eigenen Haushalt lehrte Thrall, dass sie auch etwas anderes sein konnten. Ohne Blackmoore hätte es keinen Thrall gegeben, und ohne Thrall keine neue {link:horde}Horde{/link}.]=],
		},
		{
			title = "Der Sohn eines Verräters",
			text = [=[Blackmoore kämpfte gut im Zweiten Krieg und war für seinen Zorn auf die {link:orcs}Orcs{/link} bekannt. Doch er trug einen schweren Namen. Sein Vater war des Hochverrats überführt worden, und das Getuschel verfolgte den Sohn sein ganzes Leben lang. Er trank, um sich der Schlacht zu stellen, und er trank mehr, als der Krieg vorüber war. Als ihm {link:durnholde-keep}Durnholde{/link} und die Lager übertragen wurden, wuchs seine Macht, und mit ihr seine Laster.]=],
		},
		{
			title = "Das Orckind",
			text = [=[Auf der Jagd mit seinem Diener Tammis Foxton fand Blackmoore einen {link:orcs}Orcs{/link}äugling zwischen den Leichen seiner ermordeten Eltern. Er trug das Kind nach {link:durnholde-keep}Durnholde{/link} und nannte es {link:thrall}Thrall{/link}. Er ließ den Jungen lesen, schreiben und kämpfen lehren, und er schickte ihn in {link:gurubashi-arena}die Arena{/link} gegen die Champions anderer Fürsten. Insgeheim träumte er von mehr. Thrall würde eines Tages ein Heer von Orcs aus den {link:camping}Lagern{/link} anführen, und durch ihn würde Blackmoore herrschen. Er war oft grausam zu dem Jungen und manchmal gütig, und nie sah er den Unterschied so, wie Thrall ihn sah.]=],
		},
		{
			title = "Der Fall von Durnholde",
			text = [=[{link:thrall}Thrall{/link} entkam mit der Hilfe von Tammis' Tochter {link:taretha-foxton}Taretha Foxton{/link}, die Blackmoore gegen ihren Willen zu seiner Geliebten gemacht hatte. Jahre später kehrte der {link:orcs}Orc{/link} an der Spitze einer freien {link:horde}Horde{/link} zurück und zerschlug die Lager eines nach dem anderen. In der Nacht vor der Belagerung erfuhr Blackmoore, dass Taretha sich heimlich mit Thrall getroffen hatte. Er ließ sie hinrichten. Als Thrall zur Verhandlung an die Tore kam, warf ein betrunkener Blackmoore ihren Kopf von den Mauern hinab. Die Orcs stürmten die Burg. Thrall fand Blackmoore darin und erschlug ihn im Zweikampf. Dann rief er den Geist der Erde an, und {link:durnholde-keep}Durnholde{/link} stürzte über dem Leichnam seines Herrn zusammen.]=],
		},
	},
	chapters = {
		{
			title = "Blackmoores Vermächtnis",
			hint = [=[Findet heraus, was der Fürst des Syndikats mit den Orcs vorhat.]=],
			text = [=[Blackmoores Ehrgeiz starb nicht mit ihm. Der {link:orcs}Orc{/link} {link:gol-dir}Gol'dir{/link}, ein Gefangener des {link:syndicate}Syndikats{/link}, erfuhr, dass dessen Fürst {link:lord-aliden-perenolde}Aliden Perenolde{/link} Blackmoore seinen Lehrmeister genannt hatte. Perenolde wollte die Orcs, die sich ihm widersetzten, zu Sklaven machen, wie es sein Vater und sein Lehrer vor ihm geplant hatten.]=],
		},
	},
	mentions = {
		{ text = "Blackmoores Vermächtnis" },
