Translate("deDE", "taretha-foxton", {
	title = "Taretha Foxton",
	subtitle = "Freundin Thralls",
	allegiance = "Burg Durnholde",
	aliases = { "Taretha", "Tari" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Taretha Foxton war ein Mädchen aus {link:durnholde-keep}Burg Durnholde{/link}, die Tochter von Blackmoores Diener Tammis Foxton. Sie war das, was einer Familie für den jungen {link:thrall}Thrall{/link} am nächsten kam. Sie schrieb ihm heimlich, als er ein Sklave war, half ihm zu entkommen und bezahlte seine Freiheit mit ihrem Leben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Von {link:aedelas-blackmoore}Blackmoore{/link} lernte {link:thrall}Thrall{/link}, was Grausamkeit war. Von Taretha lernte er, dass {link:humans}Menschen{/link} gut sein konnten. Ihr Andenken ist ein Grund dafür, dass der Kriegshäuptling der {link:horde}Horde{/link} nie die ganze Menschheit gehasst hat.]=],
		},
		{
			title = "Taten",
			text = [=[• Als Kind sah sie, dass der {link:orcs}Orcs{/link}äugling das Fleisch nicht essen konnte, das man ihm gab, und rettete so sein Leben. Ihre Mutter säugte ihn.
• Sie versteckte Notizen in den Büchern, die sie in Thralls Zelle trug, und jahrelang schrieben sie einander.
• Als {link:thrall}Thrall{/link} aus {link:durnholde-keep}Durnholde{/link} floh, legte sie ein Feuer als Ablenkung und ließ ihm einen Umhang zurück, um das Tor zu passieren. Sie ging nicht mit ihm, aus Furcht davor, was {link:aedelas-blackmoore}Blackmoore{/link} ihrer Familie antun würde.
• In der Nacht, bevor sein Heer nach Durnholde kam, traf sie Thrall heimlich. Blackmoore ließ ihr folgen, und er ließ sie töten.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Aufzeichnung sagt, wie Tarethas Anhänger in die Hände der Fürsten von {link:alterac-mountains}Alterac{/link} gelangte oder wo Taretha ruht.]=],
		},
	},
	chapters = {
		{
			title = "Tarethas Geschenk",
			hint = "Holt den Anhänger zurück, den der Kriegshäuptling begehrt.",
			text = [=[Lange nach ihrem Tod kamen {link:orcs}Orcs{/link}, die {link:thrall}Thrall{/link} geschickt hatte, nach {link:hillsbrad-foothills}Hillsbrad{/link}, um einen einzigen Anhänger zu holen, der ihr gehört hatte. Sie fanden ihn um den Hals von {link:elysa}Elysa{/link}, der Geliebten von {link:lord-aliden-perenolde}Aliden Perenolde{/link}. Sie gab ihn bereitwillig her. Der Orc, der ihn entgegennahm, konnte nicht verstehen, warum der Kriegshäuptling so viel für ein so kleines Ding aufwenden würde.]=],
		},
	},
	mentions = {
		{ text = "Blackmoores Vermächtnis" },
		{ text = "Fürst {link:lord-aliden-perenolde}Aliden Perenolde{/link}" },
		{ text = "Tarethas Geschenk" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "ihr Freund, den sie einen Bruder nannte" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "ihr Herr und ihr Mörder" },
		{ id = "krusk", name = "Krusk", note = "holte ihren Anhänger für den Kriegshäuptling zurück" },
	},
})

Translate("deDE", "loremaster-dibbs", {
	title = "Wissenshüter Dibbs",
	subtitle = "Gelehrter von Southshore",
	found = "Southshore",
	hint = "Sucht den alten Gelehrten von Southshore auf.",
	allegiance = "Southshore · Allianz",
	aliases = { "Dibbs" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Wissenshüter Dibbs ist der Gelehrte von {link:southshore}Southshore{/link}, ein alter Mann der Bücher, der näher an den Ruinen von {link:alterac-mountains}Alterac{/link} lebt als jeder andere Gelehrte der {link:alliance}Allianz{/link}. Er trauert um die Bibliotheken dieses gefallenen Königreichs. Wenn ein seltsamer Brief oder ein Fetzen verzauberten Pergaments aus den Bergen herabkommt, bringt man ihn zu ihm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dibbs ist das Gedächtnis von {link:southshore}Southshore{/link} und sein Deuter von Rätseln. Durch seine Hände gehen die verlorenen Bücher von {link:alterac-mountains}Alterac{/link} und die geheimen Briefe des {link:syndicate}Syndikats{/link}. Er kennt die Grenzen seiner eigenen Gelehrsamkeit, und er weiß, wen er jenseits davon fragen muss.]=],
		},
		{
			title = "Taten",
			text = [=[• Er leitet die Suche nach Büchern, die die {link:ogres}Oger{/link} aus den {link:ruins-of-alterac}Ruinen von Alterac{/link} geplündert haben.
• Er sucht den {i}Arm of Gri'lek{/i}, ein Buch uralter Trollüberlieferung, dessen letzte bekannte vollständige Abschrift die Ruinen bargen.
• Er schickt die geborgenen Bücher an {link:milton-sheaf}Milton Sheaf{/link} für die {link:royal-library}Königliche Bibliothek{/link} von {link:stormwind-city}Stormwind{/link}.
• Er schickt die verschlüsselten Briefe des Syndikats an {link:prospector-stormpike}Prospektor Stormpike{/link} in {link:ironforge}Ironforge{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Bücher von Alterac",
			hint = "Holt die Folianten von Alterac für den Wissenshüter zurück.",
			text = [=[{link:alterac-mountains}Alterac{/link} hatte vor seinem Fall eine große Bibliothek. Die {link:crushridge-ogres}Crushridge-Oger{/link} leben nun zwischen ihren Ruinen, und sie haben für Bücher keine andere Verwendung, als sie zu verbrennen oder zu zertrampeln. Dibbs ist zu alt für den Aufstieg. Also gehen andere an seiner Stelle, und sie bringen zurück, was die {link:ogres}Oger{/link} noch nicht zerstört haben. Den {i}Arm of Gri'lek{/i} behält er, um ihn zu studieren, und den Rest schickt er nach {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Der verschlüsselte Brief",
			hint = [=[Bringt dem Wissenshüter die Chiffre, die beim Syndikat gefunden wurde.]=],
			text = [=[Der Brief, der bei den Dieben des Syndikats gefunden wurde, war in einer Chiffre geschrieben, die Dibbs nie gesehen hatte. Er gab es zu und schickte ihn an seinen Freund in {link:ironforge}Ironforge{/link} weiter. Als er endlich gelesen wurde, sprach er von einer Macht hinter dem {link:syndicate}Syndikat{/link}, die nichts mit den Adligen von {link:alterac-mountains}Alterac{/link} zu tun hatte.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:southshore}Southshore{/link}, entsandt von {link:milton-sheaf}Milton Sheaf{/link}]=],
		},
		{ text = "Wissen bewahren" },
		{ text = "Zurück zu {link:milton-sheaf}Milton{/link}" },
		{ text = "Verschlüsselter Brief" },
		{ text = "Brief an {link:stormpike-guard}Stormpike{/link}" },
		{ text = "Das verzauberte Pergament" },
		{ text = "Stormpikes Entschlüsselung" },
	},
	bonds = {
		{ id = "milton-sheaf", name = "Milton Sheaf", note = "der Bibliothekar von Stormwind" },
		{ id = "prospector-stormpike", name = "Prospektor Stormpike", note = "liest seine Chiffren" },
		{ id = "magistrate-henry-maleb", name = "Magistrat Henry Maleb", note = "erfährt, was die Briefe enthüllen" },
	},
})

Translate("deDE", "magistrate-henry-maleb", {
	title = "Magistrat Henry Maleb",
	subtitle = "Magistrat von Southshore",
	found = "Das Rathaus von Southshore",
	hint = "Sprecht mit dem Magistrat, der Southshore regiert.",
	allegiance = "Southshore · Allianz",
	aliases = { "Maleb", "Magistrat Maleb" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Henry Maleb regiert {link:southshore}Southshore{/link}. Er trat sein Amt an, nachdem der letzte Magistrat von Meuchelmördern ermordet worden war, die niemand fasste. Seine Untersuchung weist auf das {link:syndicate}Syndikat{/link}, den Bund der gefallenen Adligen von {link:alterac-mountains}Alterac{/link}. Dann wird ein Vertrag über seinen eigenen Tod gefunden, gesiegelt mit dem Ring eines Adligen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Kämpfer gegen die Lager des Syndikats nördlich von {link:tarren-mill}Tarrens Mühle{/link} und in {link:strahnbrad}Strahnbrad{/link}.
• Er verlangt die Siegelringe der verborgenen Adligen des Syndikats.
• Er setzt einen Preis auf {link:baron-vardus}Baron Vardus{/link} aus, den Fürsten, der sein Todesurteil unterzeichnete.]=],
		},
	},
	chapters = {
		{
			title = "Die Argus Wake",
			hint = "Folgt den Briefen des Syndikats bis zu ihrer Quelle.",
			text = [=[Der entschlüsselte Brief war nicht das Werk von Dieben oder Adligen. Sein Verfasser, {link:nagaz}Nagaz{/link}, diente etwas, das sich {link:argus-wake}Argus Wake{/link} nannte. Maleb ließ ihn jagen, doch er fürchtete, dass Nagaz nur der Diener einer größeren Macht war.]=],
		},
	},
	mentions = {
		{ text = "Meuchelmörder des Syndikats" },
		{ text = "Furchteinflößende Pläne" },
		{ text = "Edle Tode" },
		{ text = "Vertrag des Meuchelmörders" },
		{ text = "Das Ende des Barons" },
		{ text = "Weitere Rätsel" },
		{ text = "Dunkler Rat" },
	},
	bonds = {
		{ id = "loremaster-dibbs", name = "Wissenshüter Dibbs", note = "liest die Briefe" },
		{ id = "marshal-redpath", name = "Marschall Redpath", note = "befehligt seine Wache" },
	},
})

Translate("deDE", "marshal-redpath", {
	title = "Marschall Redpath",
	subtitle = "Marschall von Southshore",
	found = "Southshore",
	hint = [=[Sprecht mit dem Marschall, der die Wache von Southshore befehligt.]=],
	allegiance = "Southshore · Allianz",
	aliases = { "Redpath" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marschall Redpath befehligt die Wache von {link:southshore}Southshore{/link}. Er behält jede Bedrohung der Stadt im Auge: die {link:murlocs}Murlocs{/link} des Weststrands, die {link:naga}Naga{/link} des Oststrands und die {link:crushridge-ogres}Crushridge-Oger{/link}, die aus {link:alterac-mountains}Alterac{/link} herabkommen könnten, wenn man sie in Ruhe ließe. Er verlangt Beweise, und er bezahlt dafür.]=],
		},
