			title = "Taten",
			text = [=[• Er setzt ein Kopfgeld auf die Knöchel der {link:crushridge-ogres}Crushridge-Oger{/link} aus.
• Er schickt {link:lieutenant-farren-orinelle}Leutnant Farren Orinelle{/link} gegen die {link:murlocs}Murlocs{/link}, dann gegen die {link:naga}Naga{/link}.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Die Geschichten des Zweiten Krieges nennen einen Marcus Redpath als Vorsteher von {link:southshore}Southshore{/link}, als die Flüchtlinge aus {link:stormwind-city}Stormwind{/link} an Land gingen. Der Marschall könnte dieser Mann sein. Eine andere Familie dieses Namens, die Redpaths aus {link:darrowshire}Darrowshire{/link}, unter ihnen die kleine {link:pamela-redpath}Pamela Redpath{/link}, lebte weit im Osten. Keine Aufzeichnung sagt, ob er mit ihnen verwandt ist.]=],
		},
	},
	mentions = {
		{ text = "Kopfgeld auf {link:crushridge-ogres}Crushridge{/link}" },
		{ text = "Kriegstreiber der {link:crushridge-ogres}Crushridge{/link}" },
		{ text = "Farrens Beweis" },
	},
	bonds = {
		{ id = "lieutenant-farren-orinelle", name = "Leutnant Farren Orinelle", note = "sein widerwilliger Offizier" },
		{ id = "magistrate-henry-maleb", name = "Magistrat Henry Maleb", note = "regiert die Stadt, die er bewacht" },
	},
})

