})

Translate("deDE", "raleigh-the-devout", {
	title = "Raleigh der Fromme",
	subtitle = "Ein Kreuzfahrer, der sich abwandte",
	found = "Das Obergeschoss des Gasthauses von Southshore",
	hint = [=[Sucht den einstigen Kreuzfahrer, der sich im Obergeschoss des Gasthauses von Southshore aufhält.]=],
	allegiance = "Heiliges Licht",
	aliases = { "Raleigh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Raleigh der Fromme diente einst mit Stolz dem {link:scarlet-crusade}Scharlachroten Kreuzzug{/link}. Er glaubte an dessen Sache, die Welt von den Untoten zu befreien. Im Kloster des Kreuzzugs sah er, wie Unschuldige gefoltert wurden, der Seuche beschuldigt aus keinem anderen Grund, als dass sie nicht dessen Wappenrock trugen. Er ging fort, und nun lebt er still in {link:southshore}Southshore{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Manche im Kreuzzug glauben noch immer, Raleigh sei einer der Ihren. Jene, die sie zu ihm schicken, erfahren stattdessen die Wahrheit über den Orden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er ruft im Namen des {link:holy-light}Heiligen Lichts{/link} zum Tod der Anführer des {link:scarlet-monastery}Scharlachroten Klosters{/link} auf, damit die wahre Sache eines Tages neu entfacht werden kann.]=],
		},
	},
	mentions = {
		{ text = "Den scharlachroten Pfad hinab" },
		{ text = "Im Namen des Lichts" },
	},
	bonds = {
		{ id = "scarlet-crusade", name = "Scharlachroter Kreuzzug", note = "der Orden, dem er abschwor" },
	},
})

