})

Translate("deDE", "tom-half-fish-wilson", {
	title = "Tom „Halbfisch“ Wilson",
	subtitle = "Alter Seemann von Southshore",
	found = "Die Docks von Southshore",
	hint = "Findet den alten Seemann an den Docks von Southshore.",
	allegiance = "Southshore",
	aliases = { "Halbfisch" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tom Wilson, den alle Halbfisch nennen, lebt an den Docks von {link:southshore}Southshore{/link}. Er hegt einen Groll gegen einen Mann im {link:menethil-harbor}Hafen von Menethil{/link} namens {link:bart-tidewater}Bart Tidewater{/link}, der sich Kapitän der {i}Maiden's Virtue{/i} nennt. Tom sagt, Bart sei gar kein Kapitän, nur ein Schauspieler, der sein Schiff beim Kartenspiel gewonnen habe, und er betrüge.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Halbfisch kennt die neuen Schiffe, die in {link:southshore}Southshore{/link} anlegen, und er weiß, welches nach Menethil segelt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt {link:bart-tidewater}Bart Tidewater{/link} im Hafen von Menethil ein Geschenk, das mit seinen besten Grüßen überbracht werden soll.]=],
		},
	},
	chapters = {
		{
			title = "Ein Mangel an Tugend",
			hint = "Überbringt Halbfischs Geschenk in den Hafen von Menethil.",
			text = [=[{link:bart-tidewater}Bart Tidewater{/link} wickelte das Geschenk aus und platzte beinahe. Wie er es erzählte, war Tom derjenige, der beim Kartenspiel betrog, und er war deswegen aus ihrer Runde geworfen worden. Das Gold, das Bart danach gewann, kaufte die {i}Maiden's Virtue{/i}. Dann besann er sich auf seine Manieren und hieß den Boten in Menethil willkommen.]=],
		},
	},
	mentions = {
		{ text = "Ein Mangel an Tugend" },
	},
})

Translate("deDE", "high-executor-darthalia", {
	title = "Hochexekutor Darthalia",
	subtitle = "Hochexekutor von Tarrens Mühle",
	found = "Tarrens Mühle",
	hint = "Meldet Euch beim Hochexekutor, der Tarrens Mühle befehligt.",
	allegiance = "Verlassene · Todeswache",
	aliases = { "Darthalia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hochexekutor Darthalia befehligt die {link:forsaken}Verlassenen{/link} von {link:tarren-mill}Tarrens Mühle{/link} auf direkten Befehl von {link:varimathras}Varimathras{/link} und der Dunklen Fürstin. Ihre Aufgabe ist es, die {link:humans}Menschen{/link} von {link:hillsbrad-foothills}Hillsbrad{/link} zu zerschlagen, während die Apotheker ihre neue Seuche vollenden. Sie ist kalt, genau und schnell mit Drohungen gegen jene, die trödeln.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie befiehlt die Überfälle auf die Höfe, die Schmiede, den Rat und die Mine von {link:hillsbrad-foothills}Hillsbrad{/link} sowie die Belagerung von {link:dun-garok}Dun Garok{/link}.
• Sie setzt Kopfgelder auf Diebe des Syndikats und auf {link:humans}Menschen{/link} aus, die wegen Mordes an Verlassenen gesucht werden.
• Sie empfiehlt {link:varimathras}Varimathras{/link} jene, die ihr gut dienen.]=],
		},
	},
	chapters = {
		{
			title = "Der Ruf des Raben",
			hint = "Tragt die Nachricht des Spähers nach Tarrens Mühle.",
			text = [=[Ihr Späher am {link:southpoint-tower}Southpoint-Turm{/link} schickte einen einzigen Satz: „Der Ruf des Raben aus dem Westen lockt.“ Er bedeutete, dass {link:hillsbrad-foothills}Hillsbrad{/link} bereit für den Schlag war. Darthalia begann sofort mit dem Angriff.]=],
		},
	},
	mentions = {
		{ text = "Zeit zuzuschlagen" },
		{ text = "Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link}" },
		{
			text = [=[Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link}, die Belagerung von {link:dun-garok}Dun Garok{/link}]=],
		},
		{
			text = [=[Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link}, an {link:varimathras}Varimathras{/link}]=],
		},
		{ text = "GESUCHT: Mitglieder des Syndikats" },
		{ text = "GESUCHT: {link:baron-vardus}Baron Vardus{/link}" },
		{ text = "Gefährlich!" },
	},
	bonds = {
		{ id = "varimathras", name = "Varimathras", note = "ihr Befehlshaber" },
		{ id = "deathstalker-lesh", name = "Todespirscherin Lesh", note = "ihre Späherin" },
		{ id = "captain-ironhill", name = "Hauptmann Ironhill", note = "ihr Feind in Dun Garok" },
	},
})

Translate("deDE", "deathstalker-lesh", {
	title = "Todespirscherin Lesh",
	subtitle = "Späherin des Southpoint-Turms",
	found = "Southpoint-Turm",
	hint = [=[Sucht die Späherin der Verlassenen, die sich im verfallenen Turm am Westrand von Hillsbrad versteckt.]=],
	allegiance = "Verlassene · Todespirscher",
	aliases = { "Lesh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Todespirscherin Lesh hält einsame Wache in den Ruinen des Southpoint-Turms, am Westrand des Vorgebirges. Ihre Aufgabe ist die Aufklärung. Sie beobachtet die Stadt {link:hillsbrad-foothills}Hillsbrad{/link} und wartet auf den Augenblick, in dem sie am schwächsten ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link} begann mit ihrem Wort. Sie schickte eine verschlüsselte Nachricht nach {link:tarren-mill}Tarrens Mühle{/link}. Für {link:high-executor-darthalia}Darthalia{/link} bedeutete sie, dass {link:hillsbrad-foothills}Hillsbrad{/link} reif für den Angriff war, und sie ließ ihre Todeswachen auf die Höfe los.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie überwacht die Stadt {link:hillsbrad-foothills}Hillsbrad{/link} für die Verlassenen, allein und fern von {link:tarren-mill}Tarrens Mühle{/link}.
• Sie sendet das Zeichen, mit dem der Angriff beginnt.]=],
		},
	},
	mentions = {
		{ text = "Zeit zuzuschlagen" },
	},
	bonds = {
		{ id = "high-executor-darthalia", name = "Hochexekutor Darthalia", note = "empfängt ihre Nachricht" },
	},
})

Translate("deDE", "apothecary-lydon", {
	title = "Apotheker Lydon",
	subtitle = "Apotheker von Tarrens Mühle",
	found = "Tarrens Mühle",
	hint = [=[Findet den trübsinnigen Apotheker der Vereinigung in Tarrens Mühle.]=],
	allegiance = "Königliche Apothekervereinigung · Verlassene",
	aliases = { "Lydon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Apotheker Lydon ist der Mann der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} in {link:tarren-mill}Tarrens Mühle{/link}. Er ist eine trübsinnige Seele, der jeder Tag des Untodes zur Qual wird. Nur eines hebt seine Stimmung: das Leiden der Lebenden. Seine Arbeit besteht darin, die neue Seuche der Dunklen Fürstin für {link:hillsbrad-foothills}Hillsbrad{/link} bereitzumachen, und er tut sie mit Sorgfalt und schrecklicher Heiterkeit.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:master-apothecary-faranell}Meisterapotheker Faranell{/link} nennt Lydon eines der hingebungsvollsten und geschicktesten Mitglieder der Vereinigung. In seinen Elixieren wird die Seuche, die für die {link:scourge}Geißel{/link} bestimmt ist, zum ersten Mal gegen {link:humans}Menschen{/link} gerichtet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er braut drei Elixiere, des Leidens, des Schmerzes und der Qual, jedes tödlicher als das vorige.
• Er erprobt sie an seinem Frosch Umpi, am Hund von {link:farmer-ray}Bauer Ray{/link} und an gefangenen Bauern.
• Er braut für {link:apothecary-zamah}Apothekerin Zamah{/link} ein Gift gegen die {link:venture-company}Venture Co.{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}, aus dem Blut Unschuldiger, das Magiern des Syndikats abgenommen wurde.
• Er erforscht das Gift des Spinnengottes der {link:trolls}Trolle{/link} der {link:witherbark-village}Witherbark{/link} und schickt es an {link:master-apothecary-faranell}Faranell{/link}.
• An langweiligen Tagen öffnet er sein Glas mit Formaldehyd, um dessen Duft zu genießen, was Umpi nervös macht.]=],
		},
	},
	chapters = {
		{
			title = "Das Elixier des Schmerzes",
			hint = "Erprobt das Elixier des Apothekers an einem Hofhund.",
			text = [=[Lydon wollte einen Versuch. Er schickte sein Elixier zum nördlichen Hof der Felder von {link:hillsbrad-foothills}Hillsbrad{/link}, wo es Bauer Rays kleinem Hund Stanley als Leckerbissen gegeben werden sollte. Was der Hund danach wurde, musste sein Herr selbst töten.]=],
		},
		{
			title = "Das Elixier der Qual",
			hint = [=[Bringt das verseuchte Gebräu des Apothekers zu den gefangenen Bauern.]=],
			text = [=[Das letzte Elixier erforderte die stinkenden Blüten der {link:nethander-stead}Nethander-Siedlung{/link}, ein Kolloid von Faranells eigener Hand und ein Fass zwergisches Starkbier aus {link:dun-garok}Dun Garok{/link}. Dann ließ Lydon das verseuchte Fass in dem Raum abstellen, in dem die Verlassenen ihre gefangenen Bauern hielten. Er nannte es, ihnen ein Fest auszurichten.]=],
		},
	},
	mentions = {
		{
			text = [=[Reise ins {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link}, von {link:apothecary-renferrel}Apotheker Renferrel{/link}]=],
		},
		{ text = "Elixier des Leidens" },
		{ text = "Elixier des Schmerzes" },
		{ text = "Elixier der Qual" },
		{ text = "Elixier der Qual" },
		{ text = "Reise nach {link:tarren-mill}Tarrens Mühle{/link}" },
		{ text = "Blut der Unschuldigen" },
		{ text = "Gift nach {link:undercity}Undercity{/link}" },
	},
	bonds = {
		{ id = "master-apothecary-faranell", name = "Meisterapotheker Faranell", note = "sein Vorgesetzter" },
		{ id = "apothecary-renferrel", name = "Apotheker Renferrel", note = "teilt seine Erkenntnisse" },
		{ id = "apothecary-zamah", name = "Apothekerin Zamah", note = "bat ihn um ein Gift" },
		{ id = "stanley", name = "Stanley", note = "sein Versuchstier" },
		{ id = "serge-hinott", name = "Serge Hinott", note = "arbeitet an seiner Seite" },
	},
})

Translate("deDE", "serge-hinott", {
	title = "Serge Hinott",
	subtitle = "Fachkundiger Alchemist von Tarrens Mühle",
	found = "Tarrens Mühle, neben Apotheker Lydon",
	hint = [=[Sucht den Alchemisten von Tarrens Mühle, der es hasst, gestört zu werden.]=],
	allegiance = "Königliche Apothekervereinigung · Verlassene",
	aliases = { "Hinott" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Serge Hinott ist ein Alchemist von {link:tarren-mill}Tarrens Mühle{/link}, der an der Seite von {link:apothecary-lydon}Apotheker Lydon{/link} arbeitet. Er hasst Unterbrechungen und sagt es auch. Doch ein neues Gift kann seine ganze Aufmerksamkeit gewinnen. Wer so vergiftet ist, dass ihm sonst niemand helfen kann, wird zu ihm geschickt, denn es heißt, wenn irgendjemand sie heilen könne, dann Serge.]=],
		},
		{
			title = "Taten",
			text = [=[• Er heilt jene, die vom schleichenden Wahnsinn des Trolls {link:zanzil-the-outcast}Zanzil{/link} vergiftet wurden, und bewundert dabei das Gebräu.
• Er lehrt jene, die die Heilung überleben, die Herstellung von Giften.
• Sein Gegengift hält den Wahnsinn auf, doch, wie er zugibt, tut es nichts gegen den Geruch.]=],
		},
		{ title = "Unverzeichnet", text = "Keine Aufzeichnung verrät, wer Serge vor seinem Tod war." },
	},
	mentions = {
		{ text = "Hinotts Hilfe" },
		{ text = "Hinotts Hilfe" },
	},
	bonds = {
		{ id = "apothecary-lydon", name = "Apotheker Lydon", note = "sein Kollege" },
	},
})

Translate("deDE", "krusk", {
	title = "Krusk",
	subtitle = "Agent des Kriegshäuptlings",
	found = "Tarrens Mühle",
	hint = [=[Sprecht mit dem Orc in Tarrens Mühle, der auf Befehl des Kriegshäuptlings aus Durotar kam.]=],
	allegiance = "Horde · Orgrimmar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Krusk ist ein {link:orcs}Orc{/link} einer Expedition, die {link:thrall}Thrall{/link} aus {link:durotar}Durotar{/link} entsandt hat. Ihr Anführer {link:gol-dir}Gol'dir{/link} sollte herausfinden, was das {link:syndicate}Syndikat{/link} in {link:durnholde-keep}Durnholde{/link} trieb, und etwas zurückholen, das der Kriegshäuptling begehrte. Die {link:humans}Menschen{/link} überwältigten sie. Krusk entkam, doch seine Kameraden wurden gefangen genommen. Er wartet in {link:tarren-mill}Tarrens Mühle{/link}, nahe den Ruinen, in denen sein Kriegshäuptling aufwuchs.]=],
		},
		{
			title = "Taten",
			text = [=[• Er strebt die Befreiung von Drull und Tog'thar aus den Zellen von {link:durnholde-keep}Durnholde{/link} und von {link:gol-dir}Gol'dir{/link} aus den {link:camping}Lagern{/link} des Syndikats in {link:alterac-mountains}Alterac{/link} an.
• Er ruft zum Handeln gegen {link:lord-aliden-perenolde}Aliden Perenolde{/link} auf, der davon träumt, {link:orcs}Orcs{/link} zu versklaven.
• Er holt Tarethas Anhänger für den Kriegshäuptling zurück.]=],
		},
	},
	mentions = {
		{ text = "Die Rettung" },
		{ text = "Unterwanderung" },
		{ text = "{link:gol-dir}Gol'dir{/link}" },
		{ text = "Blackmoores Vermächtnis" },
		{ text = "Fürst {link:lord-aliden-perenolde}Aliden Perenolde{/link}" },
		{ text = "Tarethas Geschenk" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling" },
		{ id = "taretha-foxton", name = "Taretha Foxton", note = "ihr Anhänger" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "der alte Herr von Durnholde" },
	},
})

Translate("deDE", "ott", {
	title = "Ott",
	subtitle = "Waffenschmied von Tarrens Mühle",
	found = "Der Südrand von Tarrens Mühle",
	hint = [=[Findet den Orcschmied, der am Rand von Tarrens Mühle schlichte Klingen verkauft.]=],
