			text = [=[Ott ist ein Orcwaffenschmied, der Reisenden in {link:tarren-mill}Tarrens Mühle{/link} einfache Klingen verkauft. Er strebt nicht nach Ruhm und fertigt bescheidene, ehrliche Waffen in seinem eigenen Stil. Die Schmiede von {link:undercity}Undercity{/link} hielten einst eines seiner Schwerter für das Werk eines berühmten Meisters. Es war nur Ott.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ott beweist, dass wahres Können sich an schlichten Orten verbergen kann. Ein Paladin von {link:tyr-s-watch}Tyr's Watch{/link} erkannte es und gab ihm die Gelegenheit, es zu zeigen.]=],
		},
	},
	chapters = {
		{
			title = "Otts Meisterwerk",
			hint = [=[Bringt dem Schmied einen Auftrag, der seines Könnens würdig ist.]=],
			text = [=[Niemand hatte Ott je um eine Auftragsarbeit gebeten. Als auf Wunsch von {link:trevan-rol}Trevan Rol{/link} feine Materialien zu ihm kamen, fühlte er sich geehrt. Er schmiedete eine Mondsilberklinge, sein bestes Werk, um einen Worgen des Silberwalds namens Old Fire-Eye zu erschlagen.]=],
		},
	},
	mentions = {
		{ text = "Ein unterschätztes Talent" },
		{ text = "Otts Meisterwerk" },
		{ text = "Die Mondsilberklinge" },
	},
	bonds = {
		{ id = "trevan-rol", name = "Trevan Rol", note = "gab ihm seinen Auftrag" },
	},
})

Translate("deDE", "magus-wordeen-voidglare", {
	title = "Magus Wordeen Voidglare",
	subtitle = "Gelehrter der Verlassenen",
	found = "Tarrens Mühle",
	hint = [=[Sucht den Magus der Verlassenen, der die Zauberer von Dalaran erforscht.]=],
	allegiance = "Verlassene",
	aliases = { "Voidglare" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magus Wordeen Voidglare kam nach {link:tarren-mill}Tarrens Mühle{/link}, um die Zauberer von {link:dalaran}Dalaran{/link} zu erforschen, doch zuerst fand ihn eine Krise. Vier {link:forsaken}Verlassene{/link} flohen aus {link:undercity}Undercity{/link} mit Artefakten, die aus einem Gewölbe der Dunklen Fürstin gestohlen worden waren. Die {link:the-wizards-of-ambermill}Zauberer von Dalaran{/link} fingen sie und halten sie im {link:lordamere-internment-camp}Lordamere-Internierungslager{/link} fest. {link:sylvanas-windrunner}Sylvanas{/link} will ihre Artefakte zurück.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sucht die vier Diebe und die Artefakte, die sie gestohlen haben.
• Er schickt Jäger gegen die Zauberer und Elementare, die die Ruinen von {link:dalaran}Dalaran{/link} bewachen.
• Er erforscht die Steinmarken und Bindungsarmschienen, mit denen die Magier ihre Elementare befehligen.
• Er freut sich zu hören, dass der Dieb {link:kegan-darkmar}Kegan{/link} und die anderen Verräter ihrer gerechten Strafe zugeführt wurden.]=],
		},
	},
	mentions = {
		{ text = "Ausbruch nach innen" },
		{ text = "Patrouillen von {link:dalaran}Dalaran{/link}" },
		{ text = "Steinmarken" },
		{ text = "Armschienen der Bindung" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "seine Königin" },
		{ id = "keeper-bel-varil", name = "Hüter Bel'varil", note = "sein Gehilfe" },
	},
})

Translate("deDE", "melisara", {
