Translate("deDE", "deathguard-humbert", {
	title = "Todeswache Humbert",
	subtitle = "Todeswache von Tarrens Mühle",
	found = "Tarrens Mühle",
	hint = [=[Sprecht mit der Todeswache in Tarrens Mühle, die ihre Ausrüstung an die Zwerge verlor.]=],
	allegiance = "Verlassene · Todeswache",
	aliases = { "Humbert" },
