})

Translate("deDE", "helcular", {
	title = "Helcular",
	subtitle = "Der Beinahe-Lich",
	hint = [=[Hört den Lehrling in Tarrens Mühle an, der um seinen Meister trauert.]=],
	allegiance = "Unbekannt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Helcular war ein Zauberer des Vorgebirges, der danach strebte, ein Lich zu werden. Seine Verwandlung war fast vollendet, als eine Menge {link:humans}Menschen{/link} seinen Ritualunterschlupf in den Hügeln fand und ihn tötete. Sie begruben ihn auf dem Friedhof von {link:southshore}Southshore{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sein Lehrling, Novize Thaivand, dient nun den {link:forsaken}Verlassenen{/link} in {link:tarren-mill}Tarrens Mühle{/link}. Er hat {link:southshore}Southshore{/link} nicht vergeben.]=],
		},
	},
	chapters = {
		{
			title = "Helculars Rache",
			hint = [=[Entfacht den Stab Helculars an seinen drei Scheiterhaufen neu.]=],
			text = [=[Helcular hatte für seinen größten Zauber drei zeremonielle Scheiterhaufen entzündet: die Flammen von Azel, Veraz und Uzel, in den Höhlen der nördlichen Hügel. Sein Lehrling ließ den Stab des Zauberers in jedem Feuer aufladen und in das Grab in {link:southshore}Southshore{/link} treiben. Die Erde grollte, und der tote Zauberer erhob sich.]=],
		},
	},
	mentions = {
		{ text = "Helculars Rache" },
		{ text = "Helculars Rache" },
	},
})

Translate("deDE", "farmer-ray", {
