			title = "Zusammenfassung",
			text = [=[Ray besitzt den nördlichsten Hof der Felder von {link:hillsbrad-foothills}Hillsbrad{/link}. Er baut Nahrung für die Stadt an, und bis vor Kurzem hatte er einen kleinen Hund namens Stanley. Dann fütterte ein Fremder den Hund mit etwas, und Ray musste das Tier töten, zu dem er geworden war.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rays Hof ist eines der ersten Ziele der Verlassenen. Der Hochexekutor hat seinen Tod befohlen, als einer der Grundbesitzer, deren Felder {link:hillsbrad-foothills}Hillsbrad{/link} ernähren. Sein Name steht an der Spitze ihrer ersten Befehle des Krieges.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bestellt sein Land neben {link:farmer-getz}Bauer Getz{/link}, mit Knechten auf den Feldern.
• Er tötete seinen eigenen Hund, als das Gift ihn wahnsinnig machte.]=],
		},
	},
	mentions = {
		{ text = "Elixier des Schmerzes" },
		{ text = "Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link}" },
	},
	bonds = {
		{ id = "stanley", name = "Stanley", note = "sein Hund" },
		{ id = "farmer-getz", name = "Bauer Getz", note = "sein Nachbar" },
		{ id = "phin-odelic", name = "Phin Odelic", note = "sein Vetter" },
	},
})

