Translate("deDE", "stanley", {
	title = "Stanley",
	subtitle = "Bauer Rays Hund",
	found = "Bauer Rays Hof auf den Feldern von Hillsbrad",
	hint = [=[Sucht den kleinen Hund auf dem nördlichen Hof der Felder von Hillsbrad.]=],
	allegiance = "Bauer Ray",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stanley war Bauer Rays kleiner Hund. Ein Apotheker der Verlassenen wählte ihn aus, um ein neues Elixier zu erproben, gebraut aus dem Blut von Berglöwen. Nachdem er es genommen hatte, wuchs er zu ungeheurer Größe heran und griff jeden grausam an, der ihm nahe kam. {link:farmer-ray}Ray{/link} musste ihn töten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Stanley war das erste Lebewesen in {link:hillsbrad-foothills}Hillsbrad{/link}, das zeigte, was die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link} braute. Sein Schicksal brachte {link:phin-odelic}Phin Odelic{/link} auf die Spur einer neuen Seuche.]=],
		},
		{
			title = "Taten",
			text = [=[• Er nahm das Elixier des Schmerzes aus der Hand eines Fremden.
• Er wurde so groß und wild, dass sein eigener Herr ihn töten musste. Seine Geschichte erzählt {link:phin-odelic}Phin Odelic{/link} in {link:southshore}Southshore{/link}.]=],
		},
	},
	mentions = {
		{ text = "Elixier des Schmerzes" },
		{ text = "Hinweise auf eine neue Seuche?" },
	},
	bonds = {
		{ id = "farmer-ray", name = "Bauer Ray", note = "sein Herr" },
		{ id = "apothecary-lydon", name = "Apotheker Lydon", note = "vergiftete ihn" },
		{ id = "phin-odelic", name = "Phin Odelic", note = "sucht die Ursache seines Wahnsinns" },
	},
})

Translate("deDE", "magistrate-burnside", {
	title = "Magistrat Burnside",
	subtitle = "Magistrat von Hillsbrad",
	found = "Das Rathaus von Hillsbrad",
	hint = "Besucht das Rathaus von Hillsbrad.",
	allegiance = "Hillsbrad · Allianz",
	aliases = { "Burnside" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burnside ist der Magistrat der Stadt {link:hillsbrad-foothills}Hillsbrad{/link}. Er und sein Rat verwahren die zwei Schätze der Stadt: die Proklamation von Hillsbrad, ihre verehrte Urkunde, und das Verzeichnis ihrer Bürger. Trotz ihrer Verluste scharen sich die Leute von Hillsbrad um ihn und kämpfen weiter.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Weil die Stadt zu ihm steht, wollen die Verlassenen ihn tot sehen. Ihr Plan ist, den Magistrat und seinen Rat zu töten, die Proklamation zu verbrennen und das Verzeichnis zu stehlen, sodass {link:hillsbrad-foothills}Hillsbrad{/link} nichts mehr bleibt, um das es sich scharen kann.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt den Rat von {link:hillsbrad-foothills}Hillsbrad{/link} und verwahrt dessen Urkunde und Verzeichnis.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Aufzeichnung gibt den Wortlaut der Proklamation oder das Jahr wieder, in dem sie verfasst wurde.]=],
		},
	},
	mentions = {
		{ text = "Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link}" },
	},
	bonds = {
		{ id = "high-executor-darthalia", name = "Hochexekutor Darthalia", note = "hat seinen Tod befohlen" },
	},
})

Translate("deDE", "captain-ironhill", {
	title = "Hauptmann Ironhill",
	subtitle = "Befehlshaber von Dun Garok",
	found = "Dun Garok",
	hint = "Sucht den zwergischen Hauptmann, der Dun Garok befehligt.",
	allegiance = "Königreich Ironforge · Allianz",
	aliases = { "Ironhill" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Ironhill befehligt die Zwergenfestung {link:dun-garok}Dun Garok{/link}. Seine Bergsteiger, Schützen und Priester bewachen den Südosten von {link:hillsbrad-foothills}Hillsbrad{/link} und die {link:humans}Menschen{/link}, die dort leben. Die {link:forsaken}Verlassenen{/link} nennen seine {link:dwarves}Zwerge{/link} Knöchelschläger. Sie wissen auch genau, wo seine Festung steht, und sie wollen sie einnehmen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:dun-garok}Dun Garok{/link} ist der Beweis, dass das {link:kingdom-of-ironforge}Königreich Ironforge{/link} seine Eide gegenüber den {link:humans}Menschen{/link} des Nordens nicht vergessen hat. Ironhill hält die Linie gegen die Toten mit einer kleinen Garnison und einem kräftigen Starkbier.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt die Garnison von {link:dun-garok}Dun Garok{/link}.
• Seine Späher nahmen die Ausrüstung eines Spions der Verlassenen an sich, der sein Lager unbewacht ließ.]=],
		},
	},
	mentions = {
		{ text = "Die {link:battle-of-hillsbrad}Schlacht um Hillsbrad{/link}" },
		{ text = "Humberts Schwert" },
	},
	bonds = {
		{ id = "high-executor-darthalia", name = "Hochexekutor Darthalia", note = "hat seinen Tod befohlen" },
		{ id = "deathguard-humbert", name = "Todeswache Humbert", note = "von seinen Spähern beraubt" },
	},
})

Translate("deDE", "battle-of-hillsbrad", {
	title = "Schlacht um Hillsbrad",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schlacht um Hillsbrad ist der Krieg, den die {link:forsaken}Verlassenen{/link} von {link:tarren-mill}Tarrens Mühle{/link} nun gegen die {link:humans}Menschen{/link} des Vorgebirges führen. Ihr Ziel ist klar: die Menschen von {link:hillsbrad-foothills}Hillsbrad{/link} zu zerschlagen, bis die Apotheker die neue Seuche vollenden, und dann {link:southshore}Southshore{/link} dem Erdboden gleichzumachen.]=],
		},
		{
			title = "Der Feldzug",
			text = [=[Der Befehl kam von {link:varimathras}Varimathras{/link} an {link:high-executor-darthalia}Hochexekutor Darthalia{/link}. Als ihr Späher am {link:southpoint-tower}Southpoint-Turm{/link} meldete, dass die Stadt reif sei, begann der Angriff in Abschnitten.

• {b}Die Höfe.{/b} Die Todeswachen schlugen zuerst gegen die nördlichen Höfe und ihre Besitzer zu, um {link:hillsbrad-foothills}Hillsbrad{/link} die Nahrung abzuschneiden.
• {b}Die Obstgärten.{/b} Bauern, die in die südlichen Obstgärten flohen, wurden dort gejagt.
• {b}Die Schmiede.{/b} Der Schmied und seine Lehrlinge wurden getötet, und das Eisen der Stadt wurde fortgeschafft.
• {b}Der Rat.{/b} Der Magistrat und {link:shadow-council}der Rat{/link} wurden zum Tod bestimmt, die Urkunde der Stadt zum Verbrennen und ihr Verzeichnis zum Diebstahl.
• {b}Die Mine.{/b} Der Vorarbeiter und die Bergleute des Azurschachts wurden angegriffen, damit {link:sylvanas-windrunner}die Dunkle Fürstin{/link} ihre Soldaten aus ihm bewaffnen könne.
• {b}{link:dun-garok}Dun Garok{/link}.{/b} Zuletzt kam die Belagerung der Zwergenfestung am {link:thoradin-s-wall}Thoradinswall{/link}.]=],
		},
		{
			title = "Die andere Seite",
			text = [=[Die {link:humans}Menschen{/link} sterben nicht still. Stadtbewohner von {link:hillsbrad-foothills}Hillsbrad{/link} haben Wachen, Apotheker und Todespirscher der Verlassenen getötet und die Nachschubsendungen aus {link:undercity}Undercity{/link} überfallen. {link:high-executor-darthalia}Darthalia{/link} führt ihre Namen auf einer Kopfgeldliste.]=],
		},
		{
			title = "Die Apotheker",
			text = [=[Während die Soldaten kämpfen, erprobt {link:apothecary-lydon}Apotheker Lydon{/link} seine Elixiere an den Hunden und den gefangenen Bauern von {link:hillsbrad-foothills}Hillsbrad{/link}. Jedes ist als Schritt zu der Seuche gedacht, die {link:sylvanas-windrunner}die Dunkle Fürstin{/link} befohlen hat.]=],
		},
	},
})

Translate("deDE", "internment-camps", {
	title = "Internierungslager",
	aliases = { "Internierungslager" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nach dem {link:second-war}Zweiten Krieg{/link} wurden die überlebenden {link:orcs}Orcs{/link} nicht mit dem Schwert niedergemacht. Sie wurden in Internierungslagern überall in {link:lordaeron}Lordaeron{/link} zusammengetrieben, bewacht von den Soldaten der {link:alliance}Allianz{/link}. Die Lager sollten ein Ort sein, um einen geschlagenen Feind festzuhalten. Sie wurden zu etwas Schlimmerem.]=],
		},
		{
			title = "Die Lethargie",
			text = [=[Abgeschnitten von der dämonischen Macht, die sie angetrieben hatte, wurden die {link:orcs}Orcs{/link} in den {link:camping}Lagern{/link} teilnahmslos und im Geist krank. Viele saßen einfach hinter den Mauern und versuchten nicht zu gehen. Die {link:humans}Menschen{/link}, die sie bewachten, konnten es nicht verstehen. Manche bemitleideten sie. Andere zogen Gewinn aus ihnen.]=],
		},
		{
			title = "Durnholde",
			text = [=[Die Lager wurden von {link:durnholde-keep}Burg Durnholde{/link} im {link:hillsbrad-foothills}Vorgebirge von Hillsbrad{/link} aus beherrscht, unter Generalleutnant {link:aedelas-blackmoore}Aedelas Blackmoore{/link}. Blackmoore sah mehr als Gefangene hinter seinen Mauern. Er sah ein Heer, das seines sein könnte, wenn ein {link:orcs}Orc{/link}, den er selbst aufgezogen hatte, es anführte.]=],
		},
		{
			title = "Die Befreiung",
			text = [=[Dieser {link:orcs}Orc{/link} war {link:thrall}Thrall{/link}. Er entkam aus {link:durnholde-keep}Durnholde{/link}, fand die freien Klans und lernte die Wege des Schamanen. Mit {link:orgrim-doomhammer}Orgrim Doomhammer{/link} an seiner Seite schlug er gegen die Lager, eines nach dem anderen, und befreite die Orcs darin. Doomhammer fiel in einer dieser Schlachten. Schließlich kam Thrall nach Durnholde selbst, und die Lager fanden ihr Ende.]=],
		},
	},
})
